from typing import Sequence

def strict_valley(profile: Sequence[float], v: int) -> bool:
    return (0 <= v < len(profile)
            and all(profile[k + 1] < profile[k] for k in range(v))
            and all(profile[k] < profile[k + 1] for k in range(v, len(profile) - 1)))

def margin(profile: Sequence[float], v: int) -> float:
    if len(profile) < 2 or not 0 <= v < len(profile):
        raise ValueError("invalid profile or valley")
    return min(x - profile[v] for i, x in enumerate(profile) if i != v)

profiles = [[8.0, 5.0, 1.0, 4.0, 7.0], [9.0, 6.0, 2.0, 3.0, 8.0]]
v = 2
aggregate = [sum(row[i] for row in profiles) for i in range(len(profiles[0]))]
for label, row in [("A", profiles[0]), ("B", profiles[1]), ("aggregate", aggregate)]:
    print(label, row, "strict valley:", strict_valley(row, v), "margin:", margin(row, v))

from typing import Sequence

def margin(profile: Sequence[float], v: int) -> float:
    return min(x - profile[v] for i, x in enumerate(profile) if i != v)

def uniform_error(a: Sequence[float], b: Sequence[float]) -> float:
    if len(a) != len(b):
        raise ValueError("length mismatch")
    return max(abs(x-y) for x,y in zip(a,b))

reference = [8.0, 5.0, 1.0, 4.0, 7.0]
observed = [7.6, 4.8, 1.4, 3.7, 6.8]
v = 2
delta = margin(reference, v)
epsilon = uniform_error(reference, observed)
print("delta =", delta, "epsilon =", epsilon)
print("2 epsilon < delta:", 2*epsilon < delta)
print("observed minimizer:", min(range(len(observed)), key=observed.__getitem__))

from typing import Sequence

def variation(profile: Sequence[float]) -> float:
    return sum(abs(b-a) for a,b in zip(profile, profile[1:]))

def valley_baseline(profile: Sequence[float], v: int) -> float:
    return profile[0]-profile[v] + profile[-1]-profile[v]

clean = [8.0, 5.0, 1.0, 4.0, 7.0]
wiggly = [8.0, 5.0, 6.0, 1.0, 4.0, 7.0]
print("clean variation and baseline:", variation(clean), valley_baseline(clean, 2))
print("wiggly variation and baseline:", variation(wiggly), valley_baseline(wiggly, 3))
print("wiggly excess variation:", variation(wiggly)-valley_baseline(wiggly, 3))

